const crypto = require('crypto');
const t = $input.first().json;
if (!t.trace_key || !t.generation_name) throw new Error('trace-generation: trace_key and generation_name are required');

const traceId = crypto.createHash('sha256').update(String(t.trace_key)).digest('hex').slice(0, 32);
const spanId = crypto.randomBytes(8).toString('hex');
const nowIso = new Date().toISOString();
const nanos = (iso) => (BigInt(Date.parse(iso || nowIso)) * 1000000n).toString();
const json = (v) => (typeof v === 'string' ? v : JSON.stringify(v ?? null));
const str = (key, value) => ({ key, value: { stringValue: String(value) } });
const int = (key, value) => ({ key, value: { intValue: String(Math.trunc(Number(value))) } });

const env = $env.TN_ENV || 'unknown';
const level = ['DEBUG', 'DEFAULT', 'WARNING', 'ERROR'].includes(t.level) ? t.level : 'DEFAULT';
const usage = { input: Number(t.usage_input) || 0, output: Number(t.usage_output) || 0 };
usage.total = usage.input + usage.output;
const metadata = { ...(t.metadata || {}), n8n_execution_id: $execution.id, n8n_workflow_id: $workflow.id, trace_key: t.trace_key };

const attributes = [
  str('langfuse.observation.type', 'generation'),
  str('langfuse.trace.name', t.trace_name || t.generation_name),
  { key: 'langfuse.trace.tags', value: { arrayValue: { values: [{ stringValue: 'tn-nature' }, { stringValue: env }] } } },
  str('langfuse.trace.metadata.env', env),
  str('langfuse.environment', env),
  str('langfuse.observation.level', level),
  str('langfuse.observation.input', json(t.input)),
  str('langfuse.observation.output', json(t.output)),
  ...(t.model ? [str('langfuse.observation.model.name', t.model)] : []),
  ...(usage.total ? [str('langfuse.observation.usage_details', JSON.stringify(usage))] : []),
  ...(t.status_message ? [str('langfuse.observation.status_message', t.status_message)] : []),
  ...(t.prompt_name && t.prompt_version != null && t.prompt_version !== ''
    ? [str('langfuse.observation.prompt.name', t.prompt_name), int('langfuse.observation.prompt.version', t.prompt_version)]
    : []),
  ...Object.entries(metadata).map(([k, v]) => str(`langfuse.observation.metadata.${k}`, json(v)))
];

const body = {
  resourceSpans: [{
    resource: { attributes: [str('service.name', 'tn-nature-n8n')] },
    scopeSpans: [{
      scope: { name: 'tn-nature.trace-generation', version: '1' },
      spans: [{
        traceId,
        spanId,
        name: t.generation_name,
        kind: 1,
        startTimeUnixNano: nanos(t.start_time),
        endTimeUnixNano: nanos(t.end_time),
        attributes,
        status: level === 'ERROR' ? { code: 2, message: t.status_message || 'error' } : { code: 1 }
      }]
    }]
  }]
};
return [{ json: { body, trace_id: traceId, span_id: spanId } }];

// OTLP answers 2xx with {} or { partialSuccess: { rejectedSpans, errorMessage } }. A node error arrives as { error }.
const built = $('Build OTLP span').first().json;
const r = $input.first().json;
const errors = [];
if (r.error) errors.push({ message: String(r.error.message || r.error) });
const rejected = Number(r.partialSuccess?.rejectedSpans || 0);
if (rejected) errors.push({ message: `rejected ${rejected} span(s): ${r.partialSuccess.errorMessage || ''}` });
return [{ json: { traced: errors.length === 0, trace_id: built.trace_id, span_id: built.span_id, errors } }];
